#pragma once
static void testRoutingTemplate(const juce::File& root){
 auto dir=root.getChildFile("routing-template");dir.createDirectory();Session s(dir);s.importAudio(root.getChildFile("source.wav"),0,0);s.importAudio(root.getChildFile("source.wav"),1,0);int bus=s.addBus();s.route(1,bus);s.addSend(0,bus,-6,true);s.setMix(0,-3,0,false,false);
 juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/editor/StudioTestGain_artefacts/Release/VST3/Studio Test Gain.vst3").getFullPathName());require(types.size()==1,"Routing template fixture missing");
 auto add=[&](int track,float value){auto& p=PluginChain::add(s,track,*types[0]);p.getAudioPluginInstance()->getParameters()[0]->setValueNotifyingHost(value);p.flushPluginStateToValueTree();};add(0,0.25f);add(bus,0.75f);add(-1,0.5f);
 auto before=dir.getChildFile("before.wav");s.render(before);auto reference=readWave(before);auto path=dir.getChildFile("user-routing.swtemplate");s.saveTemplate(path);s.loadTemplate(path);
 require(s.clips().isEmpty()&&te::getAudioTracks(*s.edit).size()==3,"Routing template media/track count differs");require(s.trackAt(1).getOutput().getDestinationTrack()==&s.trackAt(bus),"Template bus route lost");require(s.trackAt(0).pluginList.getPluginsOfType<te::AuxSendPlugin>().size()==1&&s.trackAt(bus).pluginList.getPluginsOfType<te::AuxReturnPlugin>().size()==1,"Template send/return lost");require(PluginChain::external(s,-1).size()==1,"Template master lost");
 s.importAudio(root.getChildFile("source.wav"),0,0);s.importAudio(root.getChildFile("source.wav"),1,0);auto after=dir.getChildFile("after.wav");s.render(after);auto audio=readWave(after);float error=0;for(int c=0;c<2;++c)for(int i=0;i<48000;++i)error=std::max(error,std::abs(audio.getSample(c,i)-reference.getSample(c,i)));require(error<=1e-6f,"User routing/plugin template audio differs");
 auto& master=PluginChain::at(s,-1,0);auto id=master.state.getProperty("id");persistMissingPluginFixture(s,-1,0,dir.getChildFile("missing-master.vst3"));require(PluginChain::at(s,-1,0).getAudioPluginInstance()==nullptr,"Master silently substituted");PluginChain::repair(s,-1,0,*types[0]);require(PluginChain::at(s,-1,0).state.getProperty("id")==id,"Master repair lost identity");require(std::abs(PluginChain::at(s,-1,0).getAudioPluginInstance()->getParameters()[0]->getValue()-0.5f)<1e-7f,"Master repair lost parameter");
 auto* report=new juce::DynamicObject;report->setProperty("checks",7);report->setProperty("max_error",error);report->setProperty("user_created_template",true);report->setProperty("physical_device_opened",false);dir.getChildFile("routing-template-result.json").replaceWithText(juce::JSON::toString(juce::var(report)));
}
